<script setup>import { computed } from 'vue';import { useRouter } from 'vue-router';import PageHeader from '../components/PageHeader.vue';import { useAuth } from '../stores/auth';const auth=useAuth(),router=useRouter(),session=computed(()=>auth.state.session||{});async function logout(){await auth.logout();router.replace('/')}</script>
<template><div class="admin-page narrow"><PageHeader eyebrow="Account" title="Admin profile" description="Review the active browser session and security details."/><section class="admin-panel admin-profile"><div class="admin-profile-avatar">{{String(session.uid||'ZA').slice(0,2).toUpperCase()}}</div><div><p>AUTHENTICATED ADMIN</p><h2>{{session.uid}}</h2><span>Token type: {{session.token_type||'Bearer'}}</span></div><button class="admin-danger" @click="logout">Logout this session</button></section></div></template>
